For binary $A$ and $Y$, the density of $Z=(X,A,Y)$ can be written as
\begin{align*}
f(x) & \bigg( \frac{1}{4} + (a-1/2) \Delta_\pi(x) + (y-1/2)  \Delta_\mu(x)  \\
& \hspace{.4in}  + (2a-1)(2y-1) \left[ \Delta_\pi(x) \Delta_\mu(x) + a \tau(x) \left\{ \frac{1}{2} + \Delta_\pi(x) \right\}   \right] \bigg) 
\end{align*}
for $\Delta_\pi(x) = \pi(x) - 1/2$ and $\Delta_\mu(x) = \mu_0(x)-1/2$, or equivalently as
\begin{align*}
f(x) & \bigg( \frac{1}{4} + (a-1/2) \Delta_\pi(x) + (y-1/2)  \Delta_\eta(x)  \\
&\hspace{.4in} + (2a-1)(2y-1) \left[ \Delta_\pi(x) \Delta_\eta(x) + \tau(x) \left\{ \frac{1}{4} - \Delta_\pi(x)^2 \right\}   \right] \bigg) 
\end{align*}
for $\Delta_\eta(x) = \eta(x)-1/2$.

For $x_0 \in (0,1)^d$, let $\mathcal{P}$ denote the model where:
\begin{enumerate}
\item $f(x)$ is bounded above by a constant, 
\item $\pi(x)$ is $\alpha$-smooth, 
\item $\mu_0(x)$ is $\beta$-smooth, and
\item $\tau(x)$ is $\gamma$-smooth.
\end{enumerate}
Let $s \equiv (\alpha+\beta)/2$. 
Then for $n$ larger than a constant depending on $(\alpha,\beta,\gamma,d)$, the minimax rate is lower bounded as
\begin{align*}
\inf_{\widehat\tau} \sup_{P \in \mathcal{P}} \mathbb{E}_P | \widehat\tau(x_0) - \tau_P(x_0)| \gtrsim \begin{cases}
n^{-1/\left(1 + \frac{d}{2\gamma} + \frac{d}{4s} \right) } & \text{ if } s < \frac{d/4}{1+d/2\gamma}  \\
n^{-1/\left(2 + \frac{d}{\gamma}  \right) } & \text{ otherwise}  . 
\end{cases}
\end{align*}

Assume:
\begin{enumerate}
\item $\lambda_{\max}(\Omega)$ is bounded above, 

\item the basis $b$ satisfies approximating condition (6), 
\item $\widehat\pi(x) - \pi(x)$ is $\alpha$-smooth, 
\item $\widehat\mu_0(x) - \mu_0(x)$ is $\beta$-smooth.
\end{enumerate}
Then
\begin{align*}
| \mathbb{E}(\widehat{S}_j - S_j \mid D^n) | & \ \lesssim \ \left( h/k^{1/d} \right)^{2s}  + h^\gamma  \left( h/k^{1/d} \right)^{\alpha} \\
& \hspace{.5in} + \Big( h^\gamma +\| \widehat\mu_0 - \mu_0 \|_{F^*} \Big) \left( \| \widehat\pi - \pi \|_{F^*}   \| \widehat\Omega^{-1}-\Omega^{-1} \|    \right) .
\end{align*}

Assume:
\begin{enumerate}
\item $y^2$, $\widehat\pi^2$, $\widehat\mu_0^2$, and $\| \widehat\mu_0 - \mu_0 \|_{F^*}$ are all bounded above, and
\item $\lambda_{\max}(\Omega)$ is bounded above. 
\end{enumerate}
Then
\begin{align*}
\text{var}(\widehat{S}_j   \mid D^n)  & \ \lesssim \ \frac{1}{nh^d} \left( 1 + \frac{k  }{n  h^{d}} \left( 1 + \| \widehat\Omega^{-1}-\Omega^{-1} \|^2 \right) \right) .
\end{align*}

Assume the regularity conditions:
\begin{enumerate}[label=\Alph*]
\item[A.] The eigenvalues of $Q$ and $\Omega$ are bounded above and below away from zero. 
\item[B.] $\widehat\pi(x)-\pi(x)$ is $\alpha$-smooth and $\widehat\mu_0(x) - \mu_0(x)$ is $\beta$-smooth. 
\item[C.] The quantities $y^2$, $(\widehat\pi^2 , \widehat\mu_0^2)$, $\| \widehat\mu_0 - \mu_0 \|_{F^*}$, and $ \| \widehat{Q}^{-1} - {Q}^{-1} \|$  are all bounded above, and $\| d\widehat{F}^*/dF^* \|_\infty$ is bounded above and below away from zero. 
\end{enumerate}
Also assume the basis $b$  satisfies \text{H\"{o}lder}{} approximating condition (6),  and:
\begin{enumerate}
\item $\| (d\widehat{F}^*/dF^*)-1 \|_\infty \lesssim \frac{n^{-1/\left(1 + \frac{d}{2\gamma} + \frac{d}{4s} \vee \left(1 + \frac{d}{2\gamma}\right) \right) }  }{ \| \widehat\pi-\pi \|_{F^*} (\| \widehat\mu_0-\mu_0 \|_{F^*} + h^\gamma)}$, 
\item $\pi(x)$ is $\alpha$-smooth, and $\epsilon \leq \pi(x) \leq 1-\epsilon$ for some $\epsilon>0$, 
\item $\mu_0(x)$ is $\beta$-smooth, 
\item $\tau(x)$ is $\gamma$-smooth.
\end{enumerate}
Finally let the tuning parameters satisfy
$$  h \sim n^{-(1/\gamma)/\left(1 + \frac{d}{2\gamma} + \frac{d}{4s} \right) } \ \text{ and } \ k \sim n^{\left( \frac{d}{2s} - \frac{d}{\gamma} \right)/\left(1 + \frac{d}{2\gamma} + \frac{d}{4s} \right) }  $$
if $s < \frac{d/4}{1+d/2\gamma}$, or $h \sim n^{-\frac{1}{2\gamma+d} }$ and $k \sim nh^d$ otherwise. 
Then the estimator $\widehat\tau$ from Definition 2 has error upper bounded as
\begin{align*}
\mathbb{E}_P | \widehat\tau(x_0) - \tau_P(x_0)| \lesssim \begin{cases}
n^{-1/\left(1 + \frac{d}{2\gamma} + \frac{d}{4s} \right) } & \text{ if } s < \frac{d/4}{1+d/2\gamma}  \\
n^{-1/\left(2 + \frac{d}{\gamma}  \right) } & \text{ otherwise.} 
\end{cases}
\end{align*}
